:root {
  /* Blueprint Drafting Theme - grid paper and technical ink */
  --bg-primary: #0f2339;
  --bg-primary-rgb: 15, 35, 57;
  --bg-alt: #132c46;
  --bg-hover: #193756;
  --text-primary: #e9f2ff;
  --text-secondary: #bcd3f5;
  --border: #4db3ff;
  --border-rgb: 77, 179, 255;
  --accent: #ffcc66;
  --accent-hover: #ffd98f;
  --grid: rgba(var(--border-rgb), 0.5);
}

[data-theme="light"] {
  --bg-primary: #f4f8ff;
  --bg-primary-rgb: 244, 248, 255;
  --bg-alt: #e6f0ff;
  --bg-hover: #d8e7ff;
  --text-primary: #0f2339;
  --text-secondary: #33537a;
  --border: #7cbfff;
  --border-rgb: 124, 191, 255;
  --accent: #d0921e;
  --accent-hover: #f3b54c;
  --grid: rgba(var(--border-rgb), 0.5);
}

body {
  background: radial-gradient(circle at 20% 10%, rgba(var(--border-rgb), 0.18), transparent 28%), var(--bg-primary);
}

.card {
  background: var(--bg-alt);
  border: 2px solid var(--border);
  box-shadow: 0 10px 30px rgba(var(--bg-primary-rgb), 0.32);
  position: relative;
}

.card::after {
  content: '';
  position: absolute;
  inset: 8px;
  background-image: linear-gradient(var(--grid), var(--grid)), linear-gradient(90deg, var(--grid), var(--grid));
  background-size: 32px 1px, 1px 32px;
  opacity: 0.4;
  pointer-events: none;
}

.card-title {
  font-family: 'IBM Plex Sans', 'Inter', sans-serif;
  letter-spacing: 0.8px;
  color: var(--accent);
  text-transform: uppercase;
}
